compound hydrogen { formula = H2,  name = "Hydrogen"         };

reaction combustion {
    reactants = CH4 + 2*O2,
    products  = CO2 + 2*H2O,
    check     = balanced,
    energy    = exothermic 890.3 kJ/mol
};

reaction haber_bosch {
    reactants = nitrogen + 3*hydrogen,
    products  = 2*ammonia,
    check     = balanced,
    energy    = exothermic 92.0 kJ/mol
};

