printf 'element H { atomic_mass=1.008, valence=1, symbol="H" };
element O { atomic_mass=15.999, valence=2, symbol="O" };
reaction bad { reactants = H2 + O2, products = H2O, check = balanced, energy = exothermic 0 kJ };
' | ./ans --check /dev/stdin 2>&1 || true

cat > /tmp/divzero.ans << 'EOF'
element H { atomic_mass = 1.008, valence = 1, symbol = "H" };
