EOF
echo "--- div by zero ---" && ./ans --run /tmp/divzero.ans 2>&1; echo "exit: $?"

cat > /tmp/oob.ans << 'EOF'
element H { atomic_mass = 1.008, valence = 1, symbol = "H" };
let xs = [1.0, 2.0];
let y = xs[5];
EOF
echo "--- index out of range ---" && ./ans --run /tmp/oob.ans 2>&1; echo "exit: $?"

cat > /tmp/unbalanced.ans << 'EOF'
element H { atomic_mass = 1.008, valence = 1, symbol = "H" };
element O { atomic_mass = 15.999, valence = 2, symbol = "O" };
reaction bad {
