\newline\code{error: formula 'NH3' uses undeclared element 'N'} &
\statuserr \\
\file{sem3\_missing\_field.ans} &
\code{compound water} declared without required \code{name} field.
\newline\code{error: compound 'water' missing name} &
\statuserr \\
