1	#include <stdio.h>
2	#include <stdlib.h>
3	#include <string.h>
4	#include "checker.h"
5	#include "ast.h"
6	#include "error.h"
7	#include "value.h"
8	
9	/* ================================================================
10	   Global declaration tables (checker-private)
11	   ================================================================ */
12	
13	#define MAX_DECLS 256
14	
15	/* Elements: indexed by symbol (e.g. "H") */
16	static char *ck_elem_sym[MAX_DECLS];
17	static int   ck_n_elems;
18	
19	/* Compounds: name + formula string */
20	static char *ck_comp_name[MAX_DECLS];
21	static char *ck_comp_formula[MAX_DECLS];
22	static int   ck_n_comps;
23	
24	/* Reactions */
25	static char *ck_rxn_name[MAX_DECLS];
26	static int   ck_n_rxns;
27	
28	/* Functions: name + number of params + param types */
29	#define MAX_PARAMS 8
30	typedef struct {
31	    char *name;
32	    int   n_params;
33	    char *param_type[MAX_PARAMS]; /* "compound", "reaction", "element", or "" */
34	    char *param_name[MAX_PARAMS];
35	} FuncSig;
36	
37	static FuncSig ck_funcs[MAX_DECLS];
38	static int      ck_n_funcs;
39	
40	/* ================================================================
41	   Type environment (local scope for checker)
42	   ================================================================ */
43	
44	#define TENV_SLOTS 256
45	typedef struct TypeEnv {
46	    struct TypeEnv *parent;
47	    char *names[TENV_SLOTS];
48	    char *types[TENV_SLOTS]; /* "number", "string", "compound", etc. */
49	    int   count;
50	} TypeEnv;
51	
52	static TypeEnv *tenv_new(TypeEnv *parent) {
53	    TypeEnv *e = calloc(1, sizeof(TypeEnv));
54	    e->parent = parent;
55	    return e;
56	}
57	
58	static void tenv_free(TypeEnv *e) {
59	    if (!e) return;
60	    for (int i = 0; i < e->count; i++) {
61	        free(e->names[i]);
62	        free(e->types[i]);
63	    }
64	    free(e);
65	}
66	
67	static const char *tenv_lookup(TypeEnv *e, const char *name) {
68	    for (TypeEnv *cur = e; cur; cur = cur->parent) {
69	        for (int i = cur->count - 1; i >= 0; i--) {
70	            if (strcmp(cur->names[i], name) == 0) return cur->types[i];
71	        }
72	    }
73	    return NULL;
74	}
75	
76	static void tenv_bind(TypeEnv *e, const char *name, const char *type) {
77	    if (e->count >= TENV_SLOTS) return;
78	    e->names[e->count] = strdup(name);
79	    e->types[e->count] = strdup(type);
80	    e->count++;
81	}
82	
83	/* ================================================================
84	   Lookup helpers
85	   ================================================================ */
86	
87	static int elem_is_declared(const char *sym) {
88	    for (int i = 0; i < ck_n_elems; i++)
89	        if (strcmp(ck_elem_sym[i], sym) == 0) return 1;
90	    return 0;
91	}
92	
93	static const char *comp_formula_for(const char *name) {
94	    for (int i = 0; i < ck_n_comps; i++)
95	        if (strcmp(ck_comp_name[i], name) == 0) return ck_comp_formula[i];
96	    return NULL;
97	}
98	
99	static int comp_is_declared(const char *name) {
100	    return comp_formula_for(name) != NULL;
101	}
102	
103	static int rxn_is_declared(const char *name) {
104	    for (int i = 0; i < ck_n_rxns; i++)
105	        if (strcmp(ck_rxn_name[i], name) == 0) return 1;
106	    return 0;
107	}
108	
109	static FuncSig *func_sig(const char *name) {
110	    for (int i = 0; i < ck_n_funcs; i++)
111	        if (strcmp(ck_funcs[i].name, name) == 0) return &ck_funcs[i];
112	    return NULL;
113	}
114	
115	/* ================================================================
116	   Formula validation (all symbols must be declared elements)
117	   ================================================================ */
118	
119	static void check_formula_symbols(const char *formula_text, int line) {
120	    FormulaVal *f = formula_parse(formula_text);
121	    for (int i = 0; i < f->size; i++) {
122	        if (!elem_is_declared(f->symbols[i])) {
123	            error_at(line, 0,
124	                "formula '%s' uses undeclared element '%s'",
125	                formula_text, f->symbols[i]);
126	        }
127	    }
128	    formula_free(f);
129	}
130	
131	/* ================================================================
132	   Atom-map helpers for reaction balance check
133	   ================================================================ */
134	
135	typedef struct { char sym[4]; double count; } AtomEntry;
136	typedef struct { AtomEntry e[64]; int n; } AtomMap;
137	
138	static void amap_add(AtomMap *m, const char *sym, double cnt) {
139	    for (int i = 0; i < m->n; i++) {
140	        if (strcmp(m->e[i].sym, sym) == 0) { m->e[i].count += cnt; return; }
141	    }
142	    strncpy(m->e[m->n].sym, sym, 3);
143	    m->e[m->n].sym[3] = '\0';
144	    m->e[m->n].count = cnt;
145	    m->n++;
146	}
147	
148	/* Build atom map from an ND_REACTION_EXPR node.
149	 * Unknown compound species are looked up in ck_comp_formula. */
150	static void build_amap(const AstNode *rxn_expr, AtomMap *m) {
151	    for (int i = 0; i < rxn_expr->n_children; i++) {
152	        const AstNode *term = rxn_expr->children[i]; /* ND_REACTION_TERM */
153	        double coeff = 1.0;
154	        const AstNode *species = NULL;
155	
156	        if (term->n_children == 2) {
157	            coeff   = term->children[0]->num;
158	            species = term->children[1];
159	        } else if (term->n_children == 1) {
160	            species = term->children[0];
161	        } else continue;
162	
163	        const char *formula_text = NULL;
164	        if (species->kind == ND_FORMULA) {
165	            formula_text = species->text;
166	        } else if (species->kind == ND_IDENT) {
167	            formula_text = comp_formula_for(species->text);
168	        }
169	        if (!formula_text) continue;
170	
171	        FormulaVal *f = formula_parse(formula_text);
172	        for (int j = 0; j < f->size; j++)
173	            amap_add(m, f->symbols[j], coeff * f->counts[j]);
174	        formula_free(f);
175	    }
176	}
177	
178	static int amaps_equal(const AtomMap *a, const AtomMap *b) {
179	    /* Check every symbol in a matches b */
180	    for (int i = 0; i < a->n; i++) {
181	        double bc = 0;
182	        for (int j = 0; j < b->n; j++)
183	            if (strcmp(a->e[i].sym, b->e[j].sym) == 0) { bc = b->e[j].count; break; }
184	        if (a->e[i].count != bc) return 0;
185	    }
186	    /* Check every symbol in b is covered by a */
187	    for (int i = 0; i < b->n; i++) {
188	        double ac = 0;
189	        for (int j = 0; j < a->n; j++)
190	            if (strcmp(b->e[i].sym, a->e[j].sym) == 0) { ac = a->e[j].count; break; }
191	        if (b->e[i].count != ac) return 0;
192	    }
193	    return 1;
194	}
195	
196	/* ================================================================
197	   Expression type inference
198	   ================================================================ */
199	
200	static const char *check_expr(const AstNode *node, TypeEnv *tenv);
201	
202	static const char *check_call(const AstNode *call, TypeEnv *tenv) {
203	    /* call->children[0] = callee ident; [1..] = args */
204	    if (call->n_children < 1) return "unknown";
205	    const char *callee = call->children[0]->text;
206	    int n_args = call->n_children - 1;
207	
208	    /* Built-in mol() */
209	    if (strcmp(callee, "mol") == 0) {
210	        if (n_args != 1)
211	            error_at(call->line, 0, "mol() expects 1 argument, got %d", n_args);
212	        return "number";
213	    }
214	
215	    FuncSig *sig = func_sig(callee);
216	    if (!sig) {
217	        error_at(call->line, 0, "call to undeclared function '%s'", callee);
218	        return "unknown";
219	    }
220	    if (n_args != sig->n_params) {
221	        error_at(call->line, 0,
222	            "function '%s' expects %d argument(s), got %d",
223	            callee, sig->n_params, n_args);
224	        return "unknown";
225	    }
226	    /* Check typed parameters */
227	    for (int i = 0; i < sig->n_params; i++) {
228	        const char *got = check_expr(call->children[i + 1], tenv);
229	        const char *expected = sig->param_type[i];
230	        if (!expected || expected[0] == '\0') continue; /* untyped */
231	        if (strcmp(got, expected) == 0) continue;
232	        /* Allow formula where compound expected (formula-to-compound resolution) */
233	        if (strcmp(expected, "compound") == 0 && strcmp(got, "formula") == 0) continue;
234	        if (strcmp(got, "unknown") == 0) continue; /* propagate errors silently */
235	        error_at(call->children[i+1]->line, 0,
236	            "argument %d of '%s': expected %s, got %s",
237	            i + 1, callee, expected, got);
238	    }
239	    return "unknown"; /* return type not statically known */
240	}
241	
242	static const char *check_expr(const AstNode *node, TypeEnv *tenv) {
243	    if (!node) return "unknown";
244	    switch (node->kind) {
245	        case ND_NUMBER:   return "number";
246	        case ND_STRING:   return "string";
247	        case ND_CHAR:     return "char";
248	        case ND_FORMULA:  return "formula";
249	        case ND_QUANTITY: return "quantity";
250	        case ND_LIST:     return "list";
251	
252	        case ND_IDENT: {
253	            /* Check local type env first, then global declarations */
254	            const char *t = tenv_lookup(tenv, node->text);
255	            if (t) return t;
256	            if (elem_is_declared(node->text))  return "element";
257	            if (comp_is_declared(node->text))  return "compound";
258	            if (rxn_is_declared(node->text))   return "reaction";
259	            if (func_sig(node->text))          return "function";
260	            if (strcmp(node->text, "mol") == 0) return "function";
261	            error_at(node->line, 0, "undeclared name '%s'", node->text);
262	            return "unknown";
263	        }
264	
265	        case ND_UNARY: {
266	            const char *t = check_expr(node->children[0], tenv);
267	            if (strcmp(t, "number") != 0 && strcmp(t, "unknown") != 0)
268	                error_at(node->line, 0, "unary '-' requires number, got %s", t);
269	            return "number";
270	        }
271	
272	        case ND_BINARY: {
273	            const char *ltype = check_expr(node->children[0], tenv);
274	            const char *rtype = check_expr(node->children[1], tenv);
275	            const char *op    = node->text;
276	            if (strcmp(op, "+") == 0 || strcmp(op, "-") == 0 ||
277	                strcmp(op, "*") == 0 || strcmp(op, "/") == 0) {
278	                if (strcmp(ltype, "unknown") != 0 && strcmp(ltype, "number") != 0)
279	                    error_at(node->line, 0, "operator '%s' requires numbers, left is %s", op, ltype);
280	                if (strcmp(rtype, "unknown") != 0 && strcmp(rtype, "number") != 0)
281	                    error_at(node->line, 0, "operator '%s' requires numbers, right is %s", op, rtype);
282	                return "number";
283	            }
284	            /* Comparison */
285	            (void)ltype; (void)rtype;
286	            return "bool";
287	        }
288	
289	        case ND_MEMBER: {
290	            const char *obj = check_expr(node->children[0], tenv);
291	            const char *field = node->text;
292	            if (strcmp(obj, "element") == 0) {
293	                if (strcmp(field, "atomic_mass") == 0) return "number";
294	                if (strcmp(field, "valence") == 0)     return "number";
295	                if (strcmp(field, "symbol") == 0)      return "string";
296	                error_at(node->line, 0, "element has no field '%s'", field);
297	                return "unknown";
298	            }
299	            if (strcmp(obj, "compound") == 0) {
300	                if (strcmp(field, "formula") == 0) return "formula";
301	                if (strcmp(field, "name") == 0)    return "string";
302	                error_at(node->line, 0, "compound has no field '%s'", field);
303	                return "unknown";
304	            }
305	            if (strcmp(obj, "reaction") == 0) {
306	                if (strcmp(field, "reactants") == 0 || strcmp(field, "products") == 0)
307	                    return "reaction_side";
308	                error_at(node->line, 0, "reaction has no field '%s'", field);
309	                return "unknown";
310	            }
311	            return "unknown";
312	        }
313	
314	        case ND_INDEX: {
315	            const char *obj = check_expr(node->children[0], tenv);
316	            if (strcmp(obj, "list") == 0)          return "unknown";
317	            if (strcmp(obj, "formula") == 0)        return "number";
318	            if (strcmp(obj, "reaction_side") == 0)  return "number";
319	            return "unknown";
320	        }
321	
322	        case ND_CALL:
323	            return check_call(node, tenv);
324	
325	        default:
326	            return "unknown";
327	    }
328	}
329	
330	/* ================================================================
331	   Statement checker
332	   ================================================================ */
333	
334	static void check_stmt(const AstNode *node, TypeEnv *tenv);
335	
336	static void check_block(const AstNode *block, TypeEnv *tenv) {
337	    for (int i = 0; i < block->n_children; i++)
338	        check_stmt(block->children[i], tenv);
339	}
340	
341	static void check_stmt(const AstNode *node, TypeEnv *tenv) {
342	    if (!node) return;
343	    switch (node->kind) {
344	        case ND_VAR_DECL: {
345	            const char *t = check_expr(node->children[0], tenv);
346	            tenv_bind(tenv, node->text, t);
347	            break;
348	        }
349	        case ND_ASSIGN:
350	        case ND_AUG_ASSIGN:
351	            check_expr(node->children[0], tenv);
352	            check_expr(node->children[1], tenv);
353	            break;
354	        case ND_PRINT:
355	            check_expr(node->children[0], tenv);
356	            break;
357	        case ND_RETURN:
358	            if (node->n_children > 0) check_expr(node->children[0], tenv);
359	            break;
360	        case ND_EXPR_STMT:
361	            check_expr(node->children[0], tenv);
362	            break;
363	        case ND_BLOCK:
364	            check_block(node, tenv);
365	            break;
366	        case ND_FOR: {
367	            /* children: [0]=var_ident, [1]=iterable, [2]=body */
368	            const char *iter_type = check_expr(node->children[1], tenv);
369	            /* Determine the loop variable type */
370	            const char *var_type = "unknown";
371	            if (strcmp(iter_type, "formula") == 0)        var_type = "element";
372	            else if (strcmp(iter_type, "list") == 0)      var_type = "unknown";
373	            else if (strcmp(iter_type, "reaction_side") == 0) var_type = "compound";
374	            TypeEnv *inner = tenv_new(tenv);
375	            tenv_bind(inner, node->children[0]->text, var_type);
376	            check_block(node->children[2], inner);
377	            tenv_free(inner);
378	            break;
379	        }
380	        case ND_IF: {
381	            /* alternating cond/block pairs, optional final else block */
382	            int i = 0;
383	            while (i + 1 < node->n_children) {
384	                check_expr(node->children[i], tenv);
385	                check_block(node->children[i+1], tenv);
386	                i += 2;
387	            }
388	            if (i < node->n_children) check_block(node->children[i], tenv);
389	            break;
390	        }
391	        default: break;
392	    }
393	}
394	
395	/* ================================================================
396	   Declaration checkers
397	   ================================================================ */
398	
399	static void check_element_decl(const AstNode *decl) {
400	    int has_mass = 0, has_val = 0, has_sym = 0;
401	    for (int i = 0; i < decl->n_children; i++) {
402	        const AstNode *field = decl->children[i];
403	        const char *key = field->text;
404	        if (strcmp(key, "atomic_mass") == 0) {
405	            has_mass++;
406	            if (field->n_children < 1 || field->children[0]->kind != ND_NUMBER)
407	                error_at(field->line, 0, "element.atomic_mass must be a number");
408	        } else if (strcmp(key, "valence") == 0) {
409	            has_val++;
410	            if (field->n_children < 1 || field->children[0]->kind != ND_NUMBER)
411	                error_at(field->line, 0, "element.valence must be a number");
412	        } else if (strcmp(key, "symbol") == 0) {
413	            has_sym++;
414	            if (field->n_children < 1 || field->children[0]->kind != ND_STRING)
415	                error_at(field->line, 0, "element.symbol must be a string");
416	        }
417	    }
418	    if (!has_mass) error_at(decl->line, 0, "element '%s' missing atomic_mass", decl->text);
419	    if (!has_val)  error_at(decl->line, 0, "element '%s' missing valence",     decl->text);
420	    if (!has_sym)  error_at(decl->line, 0, "element '%s' missing symbol",      decl->text);
421	    if (has_mass > 1 || has_val > 1 || has_sym > 1)
422	        error_at(decl->line, 0, "element '%s' has duplicate fields", decl->text);
423	}
424	
425	static void check_compound_decl(const AstNode *decl) {
426	    int has_formula = 0, has_name = 0;
427	    const char *formula_text = NULL;
428	    for (int i = 0; i < decl->n_children; i++) {
429	        const AstNode *field = decl->children[i];
430	        const char *key = field->text;
431	        if (strcmp(key, "formula") == 0) {
432	            has_formula++;
433	            if (field->n_children >= 1 && field->children[0]->kind == ND_FORMULA) {
434	                formula_text = field->children[0]->text;
435	                check_formula_symbols(formula_text, field->line);
436	            } else {
437	                error_at(field->line, 0, "compound.formula must be a formula literal");
438	            }
439	        } else if (strcmp(key, "name") == 0) {
440	            has_name++;
441	            if (field->n_children < 1 || field->children[0]->kind != ND_STRING)
442	                error_at(field->line, 0, "compound.name must be a string");
443	        }
444	    }
445	    if (!has_formula) error_at(decl->line, 0, "compound '%s' missing formula", decl->text);
446	    if (!has_name)    error_at(decl->line, 0, "compound '%s' missing name",    decl->text);
447	    if (has_formula > 1 || has_name > 1)
448	        error_at(decl->line, 0, "compound '%s' has duplicate fields", decl->text);
449	}
450	
451	static void check_reaction_decl(const AstNode *decl) {
452	    int has_reactants = 0, has_products = 0, has_check = 0, has_energy = 0;
453	    const AstNode *rxn_reactants = NULL, *rxn_products = NULL;
454	    int line = decl->line;
455	
456	    for (int i = 0; i < decl->n_children; i++) {
457	        const AstNode *field = decl->children[i];
458	        const char *key = field->text;
459	
460	        if (strcmp(key, "reactants") == 0) {
461	            has_reactants++;
462	            rxn_reactants = field->children[0]; /* ND_REACTION_EXPR */
463	            /* Validate all species formulas */
464	            for (int j = 0; j < rxn_reactants->n_children; j++) {
465	                const AstNode *term = rxn_reactants->children[j];
466	                const AstNode *sp = term->n_children == 2 ? term->children[1] : term->children[0];
467	                if (sp->kind == ND_FORMULA)
468	                    check_formula_symbols(sp->text, sp->line);
469	                else if (sp->kind == ND_IDENT && !comp_is_declared(sp->text))
470	                    error_at(sp->line, 0, "unknown compound '%s' in reaction", sp->text);
471	            }
472	        } else if (strcmp(key, "products") == 0) {
473	            has_products++;
474	            rxn_products = field->children[0];
475	            for (int j = 0; j < rxn_products->n_children; j++) {
476	                const AstNode *term = rxn_products->children[j];
477	                const AstNode *sp = term->n_children == 2 ? term->children[1] : term->children[0];
478	                if (sp->kind == ND_FORMULA)
479	                    check_formula_symbols(sp->text, sp->line);
480	                else if (sp->kind == ND_IDENT && !comp_is_declared(sp->text))
481	                    error_at(sp->line, 0, "unknown compound '%s' in reaction", sp->text);
482	            }
483	        } else if (strcmp(key, "check") == 0) {
484	            has_check++;
485	        } else if (strcmp(key, "energy") == 0) {
486	            has_energy++;
487	            if (field->n_children >= 1) {
488	                const AstNode *energy = field->children[0]; /* ND_ENERGY_EXPR */
489	                if (energy->kind == ND_ENERGY_EXPR) {
490	                    if (strcmp(energy->text, "exothermic") != 0 &&
491	                        strcmp(energy->text, "endothermic") != 0) {
492	                        error_at(energy->line, 0,
493	                            "reaction energy must be exothermic or endothermic");
494	                    }
495	                    if (energy->n_children >= 1) {
496	                        const AstNode *qty = energy->children[0];
497	                        if (qty->kind == ND_QUANTITY) {
498	                            Unit u = parse_unit(qty->text);
499	                            if (u != UNIT_KJ && u != UNIT_KJ_MOL)
500	                                error_at(qty->line, 0,
501	                                    "reaction energy unit must be kJ or kJ/mol");
502	                        }
503	                    }
504	                }
505	            }
506	        }
507	    }
508	
509	    if (!has_reactants) error_at(line, 0, "reaction '%s' missing reactants", decl->text);
510	    if (!has_products)  error_at(line, 0, "reaction '%s' missing products",  decl->text);
511	    if (!has_check)     error_at(line, 0, "reaction '%s' missing check",     decl->text);
512	    if (!has_energy)    error_at(line, 0, "reaction '%s' missing energy",    decl->text);
513	    if (has_reactants > 1 || has_products > 1 || has_check > 1 || has_energy > 1)
514	        error_at(line, 0, "reaction '%s' has duplicate fields", decl->text);
515	
516	    /* Balance check */
517	    if (rxn_reactants && rxn_products) {
518	        AtomMap left = {{{0}}, 0}, right = {{{0}}, 0};
519	        build_amap(rxn_reactants, &left);
520	        build_amap(rxn_products,  &right);
521	        if (!amaps_equal(&left, &right))
522	            error_at(line, 0,
523	                "reaction '%s' is not balanced (atom counts differ)", decl->text);
524	    }
525	}
526	
527	/* Parse a parameter text like "compound c" or just "c" */
528	static void parse_param_text(const char *text,
529	                              char **type_out, char **name_out) {
530	    const char *sp = strchr(text, ' ');
531	    if (sp) {
532	        size_t tlen = (size_t)(sp - text);
533	        *type_out = malloc(tlen + 1);
534	        memcpy(*type_out, text, tlen);
535	        (*type_out)[tlen] = '\0';
536	        *name_out = strdup(sp + 1);
537	    } else {
538	        *type_out = strdup("");
539	        *name_out = strdup(text);
540	    }
541	}
542	
543	static void check_function_decl(const AstNode *decl) {
544	    /* Parameters: all children except last (body block) */
545	    int n_params = decl->n_children - 1;
546	    TypeEnv *inner = tenv_new(NULL); /* function scope; no parent needed for checker */
547	
548	    for (int i = 0; i < n_params; i++) {
549	        const AstNode *param = decl->children[i];
550	        char *ptype, *pname;
551	        parse_param_text(param->text, &ptype, &pname);
552	
553	        /* Validate type annotation */
554	        if (ptype[0] != '\0') {
555	            if (strcmp(ptype, "element") != 0 &&
556	                strcmp(ptype, "compound") != 0 &&
557	                strcmp(ptype, "reaction") != 0) {
558	                error_at(param->line, 0,
559	                    "unknown type annotation '%s'", ptype);
560	            }
561	        }
562	        const char *bound_type = (ptype[0] != '\0') ? ptype : "unknown";
563	        tenv_bind(inner, pname, bound_type);
564	        free(ptype);
565	        free(pname);
566	    }
567	
568	    /* Check body */
569	    if (decl->n_children > 0) {
570	        AstNode *body = decl->children[decl->n_children - 1];
571	        check_block(body, inner);
572	    }
573	    tenv_free(inner);
574	}
575	
576	/* ================================================================
577	   Pass 1: collect declaration names
578	   ================================================================ */
579	
580	static void collect_declarations(const AstNode *prog) {
581	    /* Register mol() as a built-in function */
582	    ck_funcs[ck_n_funcs].name = "mol";
583	    ck_funcs[ck_n_funcs].n_params = 1;
584	    ck_funcs[ck_n_funcs].param_type[0] = "";
585	    ck_funcs[ck_n_funcs].param_name[0] = "x";
586	    ck_n_funcs++;
587	
588	    for (int i = 0; i < prog->n_children; i++) {
589	        const AstNode *node = prog->children[i];
590	        switch (node->kind) {
591	            case ND_ELEMENT_DECL:
592	                if (ck_n_elems < MAX_DECLS)
593	                    ck_elem_sym[ck_n_elems++] = node->text;
594	                break;
595	            case ND_COMPOUND_DECL: {
596	                if (ck_n_comps >= MAX_DECLS) break;
597	                ck_comp_name[ck_n_comps] = node->text;
598	                /* Extract formula string */
599	                ck_comp_formula[ck_n_comps] = "";
600	                for (int j = 0; j < node->n_children; j++) {
601	                    const AstNode *f = node->children[j];
602	                    if (strcmp(f->text, "formula") == 0 && f->n_children > 0)
603	                        ck_comp_formula[ck_n_comps] = f->children[0]->text;
604	                }
605	                ck_n_comps++;
606	                break;
607	            }
608	            case ND_REACTION_DECL:
609	                if (ck_n_rxns < MAX_DECLS)
610	                    ck_rxn_name[ck_n_rxns++] = node->text;
611	                break;
612	            case ND_FUNCTION_DECL: {
613	                if (ck_n_funcs >= MAX_DECLS) break;
614	                FuncSig *sig = &ck_funcs[ck_n_funcs++];
615	                sig->name = node->text;
616	                int n_params = node->n_children - 1;
617	                sig->n_params = n_params > MAX_PARAMS ? MAX_PARAMS : n_params;
618	                for (int j = 0; j < sig->n_params; j++) {
619	                    const AstNode *param = node->children[j];
620	                    char *ptype, *pname;
621	                    parse_param_text(param->text, &ptype, &pname);
622	                    sig->param_type[j] = ptype; /* leak is fine for course project */
623	                    sig->param_name[j] = pname;
624	                }
625	                break;
626	            }
627	            default: break;
628	        }
629	    }
630	}
631	
632	/* ================================================================
633	   Pass 2: validate each declaration and top-level statement
634	   ================================================================ */
635	
636	static void validate_all(const AstNode *prog) {
637	    TypeEnv *global_tenv = tenv_new(NULL);
638	
639	    /* Add global variable bindings as we encounter them */
640	    for (int i = 0; i < prog->n_children; i++) {
641	        const AstNode *node = prog->children[i];
642	        switch (node->kind) {
643	            case ND_ELEMENT_DECL:
644	                check_element_decl(node);
645	                tenv_bind(global_tenv, node->text, "element");
646	                break;
647	            case ND_COMPOUND_DECL:
648	                check_compound_decl(node);
649	                tenv_bind(global_tenv, node->text, "compound");
650	                break;
651	            case ND_REACTION_DECL:
652	                check_reaction_decl(node);
653	                tenv_bind(global_tenv, node->text, "reaction");
654	                break;
655	            case ND_FUNCTION_DECL:
656	                check_function_decl(node);
657	                tenv_bind(global_tenv, node->text, "function");
658	                break;
659	            case ND_VAR_DECL: {
660	                const char *t = check_expr(node->children[0], global_tenv);
661	                tenv_bind(global_tenv, node->text, t);
662	                break;
663	            }
664	            default:
665	                check_stmt(node, global_tenv);
666	                break;
667	        }
668	    }
669	    tenv_free(global_tenv);
670	}
671	
672	/* ================================================================
673	   Public API
674	   ================================================================ */
675	
676	void check_program(const AstNode *prog) {
677	    /* Reset checker tables */
678	    ck_n_elems = ck_n_comps = ck_n_rxns = ck_n_funcs = 0;
679	
680	    collect_declarations(prog);
681	    validate_all(prog);
682	}
