83	/* List types are represented as list<T> so the checker can preserve the
84	   element type through indexing and for-in loops. */
85	static int type_is_list(const char *type) {
86	    size_t len;
87	    if (!type) return 0;
88	    len = strlen(type);
89	    return len > 6 && strncmp(type, "list<", 5) == 0 && type[len - 1] == '>';
90	}
