92	static char *make_list_type(const char *elem_type) {
93	    const char *elem = elem_type ? elem_type : "unknown";
94	    size_t len = strlen(elem) + strlen("list<>") + 1;
95	    char *out = malloc(len);
96	    snprintf(out, len, "list<%s>", elem);
97	    return out;
