231	static const char *check_call(const AstNode *call, TypeEnv *tenv) {
232	    /* call->children[0] = callee ident; [1..] = args */
233	    if (call->n_children < 1) return "unknown";
234	    const char *callee = call->children[0]->text;
235	    int n_args = call->n_children - 1;
236	
237	    /* Built-in mol() */
238	    if (strcmp(callee, "mol") == 0) {
239	        if (n_args != 1)
240	            error_at(call->line, 0, "mol() expects 1 argument, got %d", n_args);
241	        return "number";
242	    }
243	
244	    FuncSig *sig = func_sig(callee);
245	    if (!sig) {
246	        error_at(call->line, 0, "call to undeclared function '%s'", callee);
247	        return "unknown";
248	    }
249	    if (n_args != sig->n_params) {
250	        error_at(call->line, 0,
251	            "function '%s' expects %d argument(s), got %d",
252	            callee, sig->n_params, n_args);
253	        return "unknown";
254	    }
255	    /* Check typed parameters */
256	    for (int i = 0; i < sig->n_params; i++) {
257	        const char *got = check_expr(call->children[i + 1], tenv);
258	        const char *expected = sig->param_type[i];
259	        if (!expected || expected[0] == '\0') continue; /* untyped */
260	        if (strcmp(got, expected) == 0) continue;
261	        if (strcmp(got, "unknown") == 0) continue; /* propagate errors silently */
262	        error_at(call->children[i+1]->line, 0,
263	            "argument %d of '%s': expected %s, got %s",
264	            i + 1, callee, expected, got);
265	    }
266	    return "unknown"; /* return type not statically known */
267	}
