442	    if (node->kind == ND_MEMBER) {
443	        const char *type = check_expr(node, tenv);
444	        error_at(node->line, 0,
445	            "record fields are read-only assignment targets");
446	        return type;
447	    }
448	
449	    if (node->kind == ND_CALL) {
450	        check_expr(node, tenv);
451	        error_at(node->line, 0,
452	            "function call cannot be an assignment target");
453	        return "unknown";
454	    }
455	
456	    check_expr(node, tenv);
457	    error_at(node->line, 0,
458	        "invalid assignment target");
459	    return "unknown";
460	}
461	
462	/* ================================================================
463	   Statement checker
464	   ================================================================ */
465	
466	static void check_stmt(const AstNode *node, TypeEnv *tenv);
467	
468	static void check_block(const AstNode *block, TypeEnv *tenv) {
469	    for (int i = 0; i < block->n_children; i++)
470	        check_stmt(block->children[i], tenv);
471	}
472	
473	static void check_stmt(const AstNode *node, TypeEnv *tenv) {
474	    if (!node) return;
475	    switch (node->kind) {
476	        case ND_VAR_DECL: {
477	            const char *t = check_expr(node->children[0], tenv);
478	            tenv_bind(tenv, node->text, t);
479	            break;
480	        }
481	        case ND_ASSIGN: {
482	            const char *ltype = check_assign_target(node->children[0], tenv);
483	            const char *rtype = check_expr(node->children[1], tenv);
484	            if (strcmp(ltype, "unknown") != 0 && strcmp(rtype, "unknown") != 0
485	                && strcmp(ltype, rtype) != 0)
486	                error_at(node->line, 0,
487	                    "assignment type mismatch: variable is %s, value is %s",
488	                    ltype, rtype);
489	            break;
490	        }
491	        case ND_AUG_ASSIGN: {
492	            const char *ltype = check_assign_target(node->children[0], tenv);
493	            const char *rtype = check_expr(node->children[1], tenv);
494	            if (strcmp(ltype, "unknown") != 0 && strcmp(ltype, "number") != 0)
495	                error_at(node->line, 0,
496	                    "augmented assignment requires number, left is %s", ltype);
497	            if (strcmp(rtype, "unknown") != 0 && strcmp(rtype, "number") != 0)
498	                error_at(node->line, 0,
499	                    "augmented assignment requires number, right is %s", rtype);
500	            break;
501	        }
502	        case ND_PRINT:
503	            check_expr(node->children[0], tenv);
504	            break;
505	        case ND_RETURN:
506	            if (node->n_children > 0) check_expr(node->children[0], tenv);
507	            break;
508	        case ND_EXPR_STMT:
509	            check_expr(node->children[0], tenv);
510	            break;
511	        case ND_BLOCK:
512	            check_block(node, tenv);
513	            break;
514	        case ND_FOR: {
515	            /* children: [0]=var_ident, [1]=iterable, [2]=body */
516	            const char *iter_type = check_expr(node->children[1], tenv);
517	            /* Determine the loop variable type */
518	            const char *var_type = "unknown";
519	            if (strcmp(iter_type, "formula") == 0)        var_type = "element";
520	            else if (type_is_list(iter_type))              var_type = list_element_type(iter_type);
521	            else if (strcmp(iter_type, "reaction_side") == 0) var_type = "compound";
522	            TypeEnv *inner = tenv_new(tenv);
523	            tenv_bind(inner, node->children[0]->text, var_type);
524	            check_block(node->children[2], inner);
525	            tenv_free(inner);
526	            break;
527	        }
528	        case ND_IF: {
529	            /* alternating cond/block pairs, optional final else block */
530	            int i = 0;
531	            while (i + 1 < node->n_children) {
532	                const char *ctype = check_expr(node->children[i], tenv);
533	                if (strcmp(ctype, "bool") != 0 && strcmp(ctype, "unknown") != 0)
534	                    error_at(node->children[i]->line, 0,
535	                        "if/elif condition must be bool, got %s", ctype);
536	                check_block(node->children[i+1], tenv);
537	                i += 2;
538	            }
539	            if (i < node->n_children) check_block(node->children[i], tenv);
540	            break;
541	        }
542	        default: break;
543	    }
544	}
545	
546	/* ================================================================
547	   Declaration checkers
548	   ================================================================ */
549	
550	static void check_element_decl(const AstNode *decl) {
551	    int has_mass = 0, has_val = 0, has_sym = 0;
552	    for (int i = 0; i < decl->n_children; i++) {
553	        const AstNode *field = decl->children[i];
554	        const char *key = field->text;
555	        if (strcmp(key, "atomic_mass") == 0) {
556	            has_mass++;
557	            if (field->n_children < 1 || field->children[0]->kind != ND_NUMBER)
558	                error_at(field->line, 0, "element.atomic_mass must be a number");
559	        } else if (strcmp(key, "valence") == 0) {
560	            has_val++;
561	            if (field->n_children < 1 || field->children[0]->kind != ND_NUMBER)
562	                error_at(field->line, 0, "element.valence must be a number");
563	        } else if (strcmp(key, "symbol") == 0) {
564	            has_sym++;
565	            if (field->n_children < 1 || field->children[0]->kind != ND_STRING)
566	                error_at(field->line, 0, "element.symbol must be a string");
567	        }
568	    }
569	    if (!has_mass) error_at(decl->line, 0, "element '%s' missing atomic_mass", decl->text);
570	    if (!has_val)  error_at(decl->line, 0, "element '%s' missing valence",     decl->text);
571	    if (!has_sym)  error_at(decl->line, 0, "element '%s' missing symbol",      decl->text);
572	    if (has_mass > 1 || has_val > 1 || has_sym > 1)
573	        error_at(decl->line, 0, "element '%s' has duplicate fields", decl->text);
574	}
575	
576	static void check_compound_decl(const AstNode *decl) {
577	    int has_formula = 0, has_name = 0;
578	    const char *formula_text = NULL;
579	    for (int i = 0; i < decl->n_children; i++) {
580	        const AstNode *field = decl->children[i];
581	        const char *key = field->text;
582	        if (strcmp(key, "formula") == 0) {
583	            has_formula++;
584	            if (field->n_children >= 1 && field->children[0]->kind == ND_FORMULA) {
585	                formula_text = field->children[0]->text;
586	                check_formula_symbols(formula_text, field->line);
587	            } else {
588	                error_at(field->line, 0, "compound.formula must be a formula literal");
589	            }
590	        } else if (strcmp(key, "name") == 0) {
591	            has_name++;
592	            if (field->n_children < 1 || field->children[0]->kind != ND_STRING)
593	                error_at(field->line, 0, "compound.name must be a string");
594	        }
595	    }
596	    if (!has_formula) error_at(decl->line, 0, "compound '%s' missing formula", decl->text);
597	    if (!has_name)    error_at(decl->line, 0, "compound '%s' missing name",    decl->text);
598	    if (has_formula > 1 || has_name > 1)
599	        error_at(decl->line, 0, "compound '%s' has duplicate fields", decl->text);
600	}
601	
602	static void check_reaction_decl(const AstNode *decl) {
603	    int has_reactants = 0, has_products = 0, has_check = 0, has_energy = 0;
604	    const AstNode *rxn_reactants = NULL, *rxn_products = NULL;
605	    int line = decl->line;
606	
607	    for (int i = 0; i < decl->n_children; i++) {
608	        const AstNode *field = decl->children[i];
609	        const char *key = field->text;
610	
611	        if (strcmp(key, "reactants") == 0) {
612	            has_reactants++;
613	            rxn_reactants = field->children[0]; /* ND_REACTION_EXPR */
614	            /* Validate all species formulas */
615	            for (int j = 0; j < rxn_reactants->n_children; j++) {
616	                const AstNode *term = rxn_reactants->children[j];
617	                const AstNode *sp = term->n_children == 2 ? term->children[1] : term->children[0];
618	                if (sp->kind == ND_FORMULA)
619	                    check_formula_symbols(sp->text, sp->line);
620	                else if (sp->kind == ND_IDENT && !comp_is_declared(sp->text))
621	                    error_at(sp->line, 0, "unknown compound '%s' in reaction", sp->text);
622	            }
623	        } else if (strcmp(key, "products") == 0) {
624	            has_products++;
625	            rxn_products = field->children[0];
626	            for (int j = 0; j < rxn_products->n_children; j++) {
627	                const AstNode *term = rxn_products->children[j];
628	                const AstNode *sp = term->n_children == 2 ? term->children[1] : term->children[0];
629	                if (sp->kind == ND_FORMULA)
630	                    check_formula_symbols(sp->text, sp->line);
631	                else if (sp->kind == ND_IDENT && !comp_is_declared(sp->text))
632	                    error_at(sp->line, 0, "unknown compound '%s' in reaction", sp->text);
633	            }
634	        } else if (strcmp(key, "check") == 0) {
635	            has_check++;
636	        } else if (strcmp(key, "energy") == 0) {
637	            has_energy++;
638	            if (field->n_children >= 1) {
639	                const AstNode *energy = field->children[0]; /* ND_ENERGY_EXPR */
640	                if (energy->kind == ND_ENERGY_EXPR) {
641	                    if (strcmp(energy->text, "exothermic") != 0 &&
642	                        strcmp(energy->text, "endothermic") != 0) {
643	                        error_at(energy->line, 0,
644	                            "reaction energy must be exothermic or endothermic");
645	                    }
646	                    if (energy->n_children >= 1) {
647	                        const AstNode *qty = energy->children[0];
648	                        if (qty->kind == ND_QUANTITY) {
649	                            Unit u = parse_unit(qty->text);
650	                            if (u != UNIT_KJ && u != UNIT_KJ_MOL)
651	                                error_at(qty->line, 0,
652	                                    "reaction energy unit must be kJ or kJ/mol");
653	                        }
654	                    }
655	                }
656	            }
657	        }
658	    }
659	
660	    if (!has_reactants) error_at(line, 0, "reaction '%s' missing reactants", decl->text);
661	    if (!has_products)  error_at(line, 0, "reaction '%s' missing products",  decl->text);
662	    if (!has_check)     error_at(line, 0, "reaction '%s' missing check",     decl->text);
663	    if (!has_energy)    error_at(line, 0, "reaction '%s' missing energy",    decl->text);
664	    if (has_reactants > 1 || has_products > 1 || has_check > 1 || has_energy > 1)
665	        error_at(line, 0, "reaction '%s' has duplicate fields", decl->text);
666	
667	    /* Balance check */
668	    if (rxn_reactants && rxn_products) {
669	        AtomMap left = {{{0}}, 0}, right = {{{0}}, 0};
670	        build_amap(rxn_reactants, &left);
671	        build_amap(rxn_products,  &right);
672	        if (!amaps_equal(&left, &right))
673	            error_at(line, 0,
674	                "reaction '%s' is not balanced (atom counts differ)", decl->text);
675	    }
676	}
677	
678	/* Parse a parameter text like "compound c" or just "c" */
679	static void parse_param_text(const char *text,
680	                              char **type_out, char **name_out) {
681	    const char *sp = strchr(text, ' ');
682	    if (sp) {
683	        size_t tlen = (size_t)(sp - text);
684	        *type_out = malloc(tlen + 1);
685	        memcpy(*type_out, text, tlen);
686	        (*type_out)[tlen] = '\0';
687	        *name_out = strdup(sp + 1);
688	    } else {
689	        *type_out = strdup("");
690	        *name_out = strdup(text);
691	    }
692	}
693	
694	static void check_function_decl(const AstNode *decl) {
695	    /* Parameters: all children except last (body block) */
696	    int n_params = decl->n_children - 1;
697	    TypeEnv *inner = tenv_new(NULL); /* function scope; no parent needed for checker */
698	
699	    for (int i = 0; i < n_params; i++) {
700	        const AstNode *param = decl->children[i];
701	        char *ptype, *pname;
702	        parse_param_text(param->text, &ptype, &pname);
703	
704	        /* Validate type annotation */
705	        if (ptype[0] != '\0') {
706	            if (strcmp(ptype, "element") != 0 &&
707	                strcmp(ptype, "compound") != 0 &&
708	                strcmp(ptype, "reaction") != 0) {
709	                error_at(param->line, 0,
710	                    "unknown type annotation '%s'", ptype);
711	            }
712	        }
713	        const char *bound_type = (ptype[0] != '\0') ? ptype : "unknown";
714	        tenv_bind(inner, pname, bound_type);
715	        free(ptype);
716	        free(pname);
717	    }
718	
719	    /* Check body */
720	    if (decl->n_children > 0) {
721	        AstNode *body = decl->children[decl->n_children - 1];
722	        check_block(body, inner);
723	    }
724	    tenv_free(inner);
725	}
726	
727	/* ================================================================
728	   Pass 1: collect declaration names
729	   ================================================================ */
730	
731	static void collect_declarations(const AstNode *prog) {
732	    /* Register mol() as a built-in function */
733	    ck_funcs[ck_n_funcs].name = "mol";
734	    ck_funcs[ck_n_funcs].n_params = 1;
735	    ck_funcs[ck_n_funcs].param_type[0] = "";
736	    ck_funcs[ck_n_funcs].param_name[0] = "x";
737	    ck_n_funcs++;
738	
739	    for (int i = 0; i < prog->n_children; i++) {
740	        const AstNode *node = prog->children[i];
741	        switch (node->kind) {
742	            case ND_ELEMENT_DECL:
743	                if (elem_is_declared(node->text)) {
744	                    error_at(node->line, 0,
745	                        "element '%s' already declared", node->text);
746	                } else if (ck_n_elems < MAX_DECLS) {
747	                    ck_elem_sym[ck_n_elems++] = node->text;
748	                }
749	                break;
750	            case ND_COMPOUND_DECL: {
751	                if (comp_is_declared(node->text)) {
752	                    error_at(node->line, 0,
753	                        "compound '%s' already declared", node->text);
754	                    break;
755	                }
756	                if (ck_n_comps >= MAX_DECLS) break;
757	                ck_comp_name[ck_n_comps] = node->text;
758	                /* Extract formula string */
759	                ck_comp_formula[ck_n_comps] = "";
760	                for (int j = 0; j < node->n_children; j++) {
761	                    const AstNode *f = node->children[j];
762	                    if (strcmp(f->text, "formula") == 0 && f->n_children > 0)
763	                        ck_comp_formula[ck_n_comps] = f->children[0]->text;
764	                }
765	                ck_n_comps++;
766	                break;
767	            }
768	            case ND_REACTION_DECL:
769	                if (rxn_is_declared(node->text)) {
770	                    error_at(node->line, 0,
771	                        "reaction '%s' already declared", node->text);
772	                } else if (ck_n_rxns < MAX_DECLS) {
773	                    ck_rxn_name[ck_n_rxns++] = node->text;
774	                }
775	                break;
776	            case ND_FUNCTION_DECL: {
777	                if (func_sig(node->text)) {
778	                    error_at(node->line, 0,
779	                        "function '%s' already declared", node->text);
780	                    break;
781	                }
782	                if (ck_n_funcs >= MAX_DECLS) break;
783	                FuncSig *sig = &ck_funcs[ck_n_funcs++];
784	                sig->name = node->text;
785	                int n_params = node->n_children - 1;
786	                sig->n_params = n_params > MAX_PARAMS ? MAX_PARAMS : n_params;
787	                for (int j = 0; j < sig->n_params; j++) {
788	                    const AstNode *param = node->children[j];
789	                    char *ptype, *pname;
790	                    parse_param_text(param->text, &ptype, &pname);
791	                    sig->param_type[j] = ptype; /* leak is fine for course project */
792	                    sig->param_name[j] = pname;
793	                }
794	                break;
795	            }
796	            default: break;
797	        }
798	    }
799	}
800	
801	/* ================================================================
802	   Pass 2: validate each declaration and top-level statement
803	   ================================================================ */
804	
805	static void validate_all(const AstNode *prog) {
806	    TypeEnv *global_tenv = tenv_new(NULL);
807	
808	    /* Add global variable bindings as we encounter them */
809	    for (int i = 0; i < prog->n_children; i++) {
810	        const AstNode *node = prog->children[i];
811	        switch (node->kind) {
812	            case ND_ELEMENT_DECL:
813	                check_element_decl(node);
814	                tenv_bind(global_tenv, node->text, "element");
815	                break;
816	            case ND_COMPOUND_DECL:
817	                check_compound_decl(node);
818	                tenv_bind(global_tenv, node->text, "compound");
819	                break;
820	            case ND_REACTION_DECL:
821	                check_reaction_decl(node);
822	                tenv_bind(global_tenv, node->text, "reaction");
823	                break;
824	            case ND_FUNCTION_DECL:
825	                check_function_decl(node);
826	                tenv_bind(global_tenv, node->text, "function");
827	                break;
828	            case ND_VAR_DECL: {
829	                const char *t = check_expr(node->children[0], global_tenv);
830	                tenv_bind(global_tenv, node->text, t);
831	                break;
832	            }
833	            default:
834	                check_stmt(node, global_tenv);
835	                break;
836	        }
837	    }
838	    tenv_free(global_tenv);
839	}
840	
841	/* ================================================================
842	   Public API
843	   ================================================================ */
844	
845	void check_program(const AstNode *prog) {
846	    /* Reset checker tables */
847	    ck_n_elems = ck_n_comps = ck_n_rxns = ck_n_funcs = 0;
848	
849	    collect_declarations(prog);
850	    validate_all(prog);
851	}
