  }

  // Fix 6: ND_IF bool condition
  case ND_IF: {
      int i = 0;
      while (i + 1 < node->n_children) {
          const char *ctype = check_expr(node->children[i], tenv);
          if (strcmp(ctype,"bool")!=0 && strcmp(ctype,"unknown")!=0)
              error_at(node->children[i]->line, 0, "if/elif condition must be bool, got %s", ctype);
          check_block(node->children[i+1], tenv);
          i += 2;
      }
      if (i < node->n_children) check_block(node->children[i], tenv);
      break;
  }

  // Duplicate detection in collect_declarations
  case ND_ELEMENT_DECL:
      if (elem_is_declared(node->text))
          error_at(node->line, 0, "element '%s' already declared", node->text);
      else if (ck_n_elems < MAX_DECLS)
          ck_elem_sym[ck_n_elems++] = node->text;
      break;
  // (similar for compound, reaction, function)
  ```

  Friend's additions to checker.c:
  ```c
  // Parametric list type helpers
  static int type_is_list(const char *type) {
      size_t len;
      if (!type) return 0;
      len = strlen(type);
      return len > 6 && strncmp(type, "list<", 5) == 0 && type[len-1] == '>';
  }
  static char *make_list_type(const char *elem_type) {
      const char *elem = elem_type ? elem_type : "unknown";
      size_t len = strlen(elem) + strlen("list<>") + 1;
      char *out = malloc(len);
      snprintf(out, len, "list<%s>", elem);
      return out;
  }
  static char *list_element_type(const char *list_type) {
      size_t len; char *out;
      if (!type_is_list(list_type)) return strdup("unknown");
      len = strlen(list_type);
      out = malloc(len - 5);
      memcpy(out, list_type + 5, len - 6);
      out[len - 6] = '\0';
      return out;
  }

  // New check_assign_target function
  static const char *check_assign_target(const AstNode *node, TypeEnv *tenv) {
      if (node->kind == ND_IDENT) {
          const char *type = check_expr(node, tenv);
          if (strcmp(type, "function") == 0) {
              error_at(node->line, 0, "function name cannot be assigned to");
              return "unknown";
          }
          return type;
      }
      if (node->kind == ND_INDEX) {
          const char *obj = check_expr(node->children[0], tenv);
          const char *idx = check_expr(node->children[1], tenv);
          if (type_is_list(obj)) {
              if (strcmp(idx,"number")!=0 && strcmp(idx,"unknown")!=0)
                  error_at(..., "list index must be number, got %s", idx);
              return list_element_type(obj);
          }
          if (strcmp(obj,"formula")==0) {
              error_at(node->line, 0, "formula atom counts are read-only assignment targets");
              return "number";
          }
          if (strcmp(obj,"reaction_side")==0) {
              error_at(node->line, 0, "reaction side coefficients are read-only assignment targets");
              return "number";
          }
          if (strcmp(obj,"unknown")!=0) error_at(node->line, 0, "assignment target is not writable");
          return "unknown";
      }
      if (node->kind == ND_MEMBER) {
          const char *type = check_expr(node, tenv);
          error_at(node->line, 0, "record fields are read-only assignment targets");
          return type;
      }
      if (node->kind == ND_CALL) {
          check_expr(node, tenv);
          error_at(node->line, 0, "function call cannot be an assignment target");
          return "unknown";
      }
      check_expr(node, tenv);
      error_at(node->line, 0, "invalid assignment target");
      return "unknown";
  }

  // ND_FOR now uses type_is_list and list_element_type
  case ND_FOR: {
      const char *iter_type = check_expr(node->children[1], tenv);
      const char *var_type = "unknown";
      if (strcmp(iter_type, "formula") == 0)           var_type = "element";
      else if (type_is_list(iter_type))                var_type = list_element_type(iter_type); // heap!
      else if (strcmp(iter_type, "reaction_side") == 0) var_type = "compound";
      TypeEnv *inner = tenv_new(tenv);
      tenv_bind(inner, node->children[0]->text, var_type);
      check_block(node->children[2], inner);
      tenv_free(inner);
      break;
  }

  // ND_MEMBER now errors on non-domain types
  if (strcmp(obj, "unknown") != 0) {
      error_at(node->line, 0,
          "member access '.%s' requires element, compound, or reaction, got %s", field, obj);
  }

  // Empty list error
  if (node->n_children == 0) {
      error_at(node->line, 0, "empty list requires an element type");
      return "list<unknown>";
  }
  ```

