194	        } else if (species->kind == ND_IDENT) {
195	            formula_text = comp_formula_for(species->text);
196	        }
197	        if (!formula_text) continue;
198	
199	        FormulaVal *f = formula_parse(formula_text);
200	        for (int j = 0; j < f->size; j++)
201	            amap_add(m, f->symbols[j], coeff * f->counts[j]);
202	        formula_free(f);
203	    }
204	}
205	
206	static int amaps_equal(const AtomMap *a, const AtomMap *b) {
207	    /* Check every symbol in a matches b */
208	    for (int i = 0; i < a->n; i++) {
209	        double bc = 0;
210	        for (int j = 0; j < b->n; j++)
211	            if (strcmp(a->e[i].sym, b->e[j].sym) == 0) { bc = b->e[j].count; break; }
212	        if (a->e[i].count != bc) return 0;
213	    }
214	    /* Check every symbol in b is covered by a */
215	    for (int i = 0; i < b->n; i++) {
216	        double ac = 0;
217	        for (int j = 0; j < a->n; j++)
218	            if (strcmp(b->e[i].sym, a->e[j].sym) == 0) { ac = a->e[j].count; break; }
219	        if (b->e[i].count != ac) return 0;
220	    }
221	    return 1;
222	}
