224	/* ================================================================
225	   Expression type inference
226	   ================================================================ */
227	
228	static const char *check_expr(const AstNode *node, TypeEnv *tenv);
229	static const char *check_assign_target(const AstNode *node, TypeEnv *tenv);
230	
231	static const char *check_call(const AstNode *call, TypeEnv *tenv) {
232	    /* call->children[0] = callee ident; [1..] = args */
233	    if (call->n_children < 1) return "unknown";
234	    const char *callee = call->children[0]->text;
235	    int n_args = call->n_children - 1;
236	
237	    /* Built-in mol() */
238	    if (strcmp(callee, "mol") == 0) {
239	        if (n_args != 1)
240	            error_at(call->line, 0, "mol() expects 1 argument, got %d", n_args);
241	        return "number";
242	    }
243	
244	    FuncSig *sig = func_sig(callee);
245	    if (!sig) {
246	        error_at(call->line, 0, "call to undeclared function '%s'", callee);
247	        return "unknown";
248	    }
249	    if (n_args != sig->n_params) {
250	        error_at(call->line, 0,
251	            "function '%s' expects %d argument(s), got %d",
252	            callee, sig->n_params, n_args);
253	        return "unknown";
254	    }
255	    /* Check typed parameters */
256	    for (int i = 0; i < sig->n_params; i++) {
257	        const char *got = check_expr(call->children[i + 1], tenv);
258	        const char *expected = sig->param_type[i];
259	        if (!expected || expected[0] == '\0') continue; /* untyped */
260	        if (strcmp(got, expected) == 0) continue;
261	        if (strcmp(got, "unknown") == 0) continue; /* propagate errors silently */
262	        error_at(call->children[i+1]->line, 0,
263	            "argument %d of '%s': expected %s, got %s",
264	            i + 1, callee, expected, got);
265	    }
266	    return "unknown"; /* return type not statically known */
267	}
268	
269	static const char *check_expr(const AstNode *node, TypeEnv *tenv) {
270	    if (!node) return "unknown";
271	    switch (node->kind) {
272	        case ND_NUMBER:   return "number";
273	        case ND_STRING:   return "string";
274	        case ND_CHAR:     return "char";
275	        case ND_FORMULA:  return "formula";
276	        case ND_QUANTITY: return "quantity";
277	        case ND_LIST: {
278	            if (node->n_children == 0) {
279	                error_at(node->line, 0,
280	                    "empty list requires an element type");
281	                return "list<unknown>";
282	            }
283	            const char *elem_type = check_expr(node->children[0], tenv);
284	            for (int i = 1; i < node->n_children; i++) {
285	                const char *t = check_expr(node->children[i], tenv);
286	                if (strcmp(elem_type, "unknown") != 0 && strcmp(t, "unknown") != 0
287	                    && strcmp(elem_type, t) != 0) {
288	                    error_at(node->children[i]->line, 0,
289	                        "list elements must all be the same type: "
290	                        "expected %s, got %s", elem_type, t);
291	                }
292	            }
293	            return make_list_type(elem_type);
294	        }
295	
296	        case ND_IDENT: {
297	            /* Check local type env first, then global declarations */
298	            const char *t = tenv_lookup(tenv, node->text);
299	            if (t) return t;
300	            if (elem_is_declared(node->text))  return "element";
301	            if (comp_is_declared(node->text))  return "compound";
302	            if (rxn_is_declared(node->text))   return "reaction";
303	            if (func_sig(node->text))          return "function";
304	            if (strcmp(node->text, "mol") == 0) return "function";
305	            error_at(node->line, 0, "undeclared name '%s'", node->text);
306	            return "unknown";
307	        }
308	
309	        case ND_UNARY: {
310	            const char *t = check_expr(node->children[0], tenv);
311	            if (strcmp(t, "number") != 0 && strcmp(t, "unknown") != 0)
312	                error_at(node->line, 0, "unary '-' requires number, got %s", t);
313	            return "number";
314	        }
315	
316	        case ND_BINARY: {
317	            const char *ltype = check_expr(node->children[0], tenv);
318	            const char *rtype = check_expr(node->children[1], tenv);
319	            const char *op    = node->text;
320	            if (strcmp(op, "+") == 0 || strcmp(op, "-") == 0 ||
321	                strcmp(op, "*") == 0 || strcmp(op, "/") == 0) {
322	                if (strcmp(ltype, "unknown") != 0 && strcmp(ltype, "number") != 0)
323	                    error_at(node->line, 0, "operator '%s' requires numbers, left is %s", op, ltype);
324	                if (strcmp(rtype, "unknown") != 0 && strcmp(rtype, "number") != 0)
325	                    error_at(node->line, 0, "operator '%s' requires numbers, right is %s", op, rtype);
326	                return "number";
327	            }
328	            /* Comparison */
329	            (void)ltype; (void)rtype;
330	            return "bool";
331	        }
332	
333	        case ND_MEMBER: {
334	            const char *obj = check_expr(node->children[0], tenv);
335	            const char *field = node->text;
336	            if (strcmp(obj, "element") == 0) {
337	                if (strcmp(field, "atomic_mass") == 0) return "number";
338	                if (strcmp(field, "valence") == 0)     return "number";
339	                if (strcmp(field, "symbol") == 0)      return "string";
340	                error_at(node->line, 0, "element has no field '%s'", field);
341	                return "unknown";
342	            }
343	            if (strcmp(obj, "compound") == 0) {
344	                if (strcmp(field, "formula") == 0) return "formula";
345	                if (strcmp(field, "name") == 0)    return "string";
346	                error_at(node->line, 0, "compound has no field '%s'", field);
347	                return "unknown";
348	            }
349	            if (strcmp(obj, "reaction") == 0) {
350	                if (strcmp(field, "reactants") == 0 || strcmp(field, "products") == 0)
351	                    return "reaction_side";
352	                error_at(node->line, 0, "reaction has no field '%s'", field);
353	                return "unknown";
354	            }
355	            if (strcmp(obj, "unknown") != 0) {
356	                error_at(node->line, 0,
357	                    "member access '.%s' requires element, compound, or reaction, got %s",
358	                    field, obj);
359	            }
360	            return "unknown";
361	        }
362	
363	        case ND_INDEX: {
364	            const char *obj = check_expr(node->children[0], tenv);
365	            const char *idx = check_expr(node->children[1], tenv);
366	            if (type_is_list(obj)) {
367	                if (strcmp(idx, "number") != 0 && strcmp(idx, "unknown") != 0)
368	                    error_at(node->children[1]->line, 0,
369	                        "list index must be number, got %s", idx);
370	                return list_element_type(obj);
371	            }
372	            if (strcmp(obj, "formula") == 0) {
373	                if (strcmp(idx, "element") != 0 && strcmp(idx, "unknown") != 0)
374	                    error_at(node->children[1]->line, 0,
375	                        "formula index must be element, got %s", idx);
376	                return "number";
377	            }
378	            if (strcmp(obj, "reaction_side") == 0) {
379	                if (strcmp(idx, "compound") != 0 && strcmp(idx, "formula") != 0
380	                    && strcmp(idx, "unknown") != 0)
381	                    error_at(node->children[1]->line, 0,
382	                        "reaction_side index must be compound, got %s", idx);
383	                return "number";
384	            }
385	            if (strcmp(obj, "unknown") != 0) {
386	                error_at(node->line, 0,
387	                    "index operator not supported for type %s", obj);
388	            }
389	            return "unknown";
390	        }
391	
392	        case ND_CALL:
393	            return check_call(node, tenv);
394	
395	        default:
396	            return "unknown";
397	    }
398	}
399	
400	static const char *check_assign_target(const AstNode *node, TypeEnv *tenv) {
401	    if (!node) return "unknown";
402	
403	    if (node->kind == ND_IDENT) {
404	        const char *type = check_expr(node, tenv);
405	        if (strcmp(type, "function") == 0) {
406	            error_at(node->line, 0,
407	                "function name cannot be assigned to");
408	            return "unknown";
409	        }
410	        return type;
411	    }
412	
413	    if (node->kind == ND_INDEX) {
414	        const char *obj = check_expr(node->children[0], tenv);
415	        const char *idx = check_expr(node->children[1], tenv);
416	
417	        if (type_is_list(obj)) {
418	            if (strcmp(idx, "number") != 0 && strcmp(idx, "unknown") != 0)
419	                error_at(node->children[1]->line, 0,
420	                    "list index must be number, got %s", idx);
421	            return list_element_type(obj);
422	        }
423	
424	        if (strcmp(obj, "formula") == 0) {
425	            error_at(node->line, 0,
426	                "formula atom counts are read-only assignment targets");
427	            return "number";
428	        }
429	
430	        if (strcmp(obj, "reaction_side") == 0) {
431	            error_at(node->line, 0,
432	                "reaction side coefficients are read-only assignment targets");
433	            return "number";
434	        }
435	
436	        if (strcmp(obj, "unknown") != 0)
437	            error_at(node->line, 0,
438	                "assignment target is not writable");
439	        return "unknown";
440	    }
441	
442	    if (node->kind == ND_MEMBER) {
443	        const char *type = check_expr(node, tenv);
444	        error_at(node->line, 0,
445	            "record fields are read-only assignment targets");
446	        return type;
447	    }
448	
449	    if (node->kind == ND_CALL) {
450	        check_expr(node, tenv);
451	        error_at(node->line, 0,
452	            "function call cannot be an assignment target");
453	        return "unknown";
454	    }
455	
456	    check_expr(node, tenv);
457	    error_at(node->line, 0,
458	        "invalid assignment target");
459	    return "unknown";
460	}
